        let mut queue = vec![TermEvent::Key(press(KeyCode::Char('y'))), TermEvent::Key(release), TermEvent::Resize(80, 24), TermEvent::Key(press(KeyCode::Char('n')))].into_iter();
        let mut pending = None;
